123	                return Err(std::io::Error::last_os_error());
124	            }
125	            if libc::syscall(
126	                libc::SYS_close_range,
127	                3u32,
128	                u32::MAX,
129	                libc::CLOSE_RANGE_CLOEXEC,
130	            ) != 0
131	            {
132	                return Err(std::io::Error::last_os_error());
