135	                (libc::RLIMIT_CORE, 0),
136	                (libc::RLIMIT_FSIZE, 0),
137	                (libc::RLIMIT_CPU, 2),
138	                (libc::RLIMIT_NOFILE, 32),
139	                (libc::RLIMIT_AS, address_space),
