1	//! Keymap-qualified Rust binding tables. No device, seat, Lua or XKB object is retained.
2	use flux_config::{Binding, Key};
3	use flux_core::Action;
4	use std::collections::{BTreeMap, BTreeSet};
5	use xkbcommon::xkb;
6	
7	const MAX_BINDINGS: usize = 4096;
8	const MAX_STRING_BYTES: usize = 4 * 1024 * 1024;
9	const MAX_LAYOUTS_PER_KEY: u32 = 32;
10	const MAX_RESOLVED_CHORDS: usize = 65_536;
11	
12	/// Lock modifiers are deliberately absent. Level3/Level5 are separate from Alt
13	/// and suppress matching because the current schema cannot name those modifiers.
14	#[derive(Clone, Copy, Default, Debug, PartialEq, Eq, PartialOrd, Ord)]
15	pub struct Modifiers {
16	    pub ctrl: bool,
17	    pub alt: bool,
18	    pub shift: bool,
19	    pub logo: bool,
20	    pub level3: bool,
21	    pub level5: bool,
22	}
23	
24	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
25	pub enum UnmappedPolicy {
26	    Reject,
27	    /// For development defaults on foreign keymaps: retain a visible list of
28	    /// inactive bindings instead of failing the whole nested startup.
29	    RetainInactive,
30	}
31	
32	#[derive(Debug, thiserror::Error)]
33	#[error("{0}")]
34	pub struct BindingError(String);
35	
36	#[derive(Default, Debug)]
37	pub struct BindingSet {
38	    actions: Vec<Action>,
39	    codes: BTreeMap<(u16, Modifiers), usize>,
40	    symbols: BTreeMap<(u32, Modifiers), usize>,
41	    inactive: Vec<usize>,
42	}
43	
44	impl BindingSet {
45	    /// Compile against all base levels of the supplied keymap. The caller must
46	    /// recompile when that keymap changes, before publishing new bindings.
47	    /// Canonical names are case sensitive; numeric aliases resolving to the same
48	    /// symbol and code/symbol overlap are rejected rather than ordered implicitly.
49	    pub fn compile(
50	        bindings: &[Binding],
51	        keymap: &xkb::Keymap,
52	        unmapped: UnmappedPolicy,
53	    ) -> Result<Self, BindingError> {
54	        let fail = |message: String| BindingError(message);
55	        if bindings.len() > MAX_BINDINGS {
56	            return Err(fail("bindings: maximum 4096".into()));
57	        }
58	        let mut result = Self::default();
59	        let mut bytes = 0usize;
60	        for (index, binding) in bindings.iter().enumerate() {
61	            binding
62	                .key
63	                .identity()
64	                .map_err(|e| fail(format!("bindings[{index}]: {e}")))?;
65	            binding
66	                .action
67	                .validate()
68	                .map_err(|e| fail(format!("bindings[{index}].action: {e}")))?;
69	            let (key_bytes, modifier_names, symbol_name, code) = match &binding.key {
70	                Key::Sym { sym } => {
71	                    let mut parts = sym.split('+').collect::<Vec<_>>();
72	                    let name = parts.pop().expect("validated nonempty chord");
73	                    (sym.len(), parts, Some(name), None)
74	                }
75	                Key::Code { code, modifiers } => (
76	                    modifiers.iter().map(String::len).sum(),
77	                    modifiers.iter().map(String::as_str).collect(),
78	                    None,
79	                    Some(*code),
80	                ),
81	            };
82	            bytes = bytes
83	                .checked_add(key_bytes)
84	                .ok_or_else(|| fail("binding string budget exceeded".into()))?;
85	            if let Action::Spawn { argv } = &binding.action {
86	                for arg in argv {
87	                    bytes = bytes
88	                        .checked_add(arg.len())
89	                        .ok_or_else(|| fail("binding string budget exceeded".into()))?;
90	                }
91	            }
92	            if bytes > MAX_STRING_BYTES {
93	                return Err(fail("binding strings exceed 4 MiB".into()));
94	            }
95	            let mut modifiers = Modifiers::default();
96	            for name in modifier_names {
97	                match name {
98	                    "Ctrl" => modifiers.ctrl = true,
99	                    "Alt" => modifiers.alt = true,
100	                    "Shift" => modifiers.shift = true,
101	                    "Super" | "Logo" => modifiers.logo = true,
102	                    _ => unreachable!("schema normalization already checked modifier tokens"),
