pub fn process_input_event<I: InputBackend>(&mut self, event: InputEvent<I>) {
    match event {
        InputEvent::Keyboard { event, .. } => {
            if self.host_focus == Some(false) {
                return;
            }
            let serial = SERIAL_COUNTER.next_serial();
            let time = Event::time(&event);

            let code = event.key_code();
            let pressed = event.state() == KeyState::Pressed;
            let Some(keyboard) = self.seat.get_keyboard() else {
                return;
            };
            let action = keyboard
                .input::<Option<flux_core::Action>, _>(
                    self,
                    code,
                    event.state(),
                    serial,
                    time,
                    |state, modifiers, handle| {
                        if !pressed {
                            return if state.suppressed_keys.remove(&code.raw()) {
                                FilterResult::Intercept(None)
                            } else {
                                FilterResult::Forward
                            };
                        }
                        if state.suppressed_keys.contains(&code.raw()) {
                            return FilterResult::Intercept(None);
                        }
                        // Smithay's actual backend/KeysymHandle code is XKB
                        // (+8), despite the backend trait's evdev wording.
                        let evdev = handle
                            .raw_code()
                            .raw()
                            .checked_sub(8)
                            .and_then(|code| u16::try_from(code).ok());
                        let action = evdev
                            .and_then(|code| {
                                state.bindings.action(
                                    code,
                                    &handle.raw_syms(),
                                    flux_input::Modifiers {
                                        ctrl: modifiers.ctrl,
                                        alt: modifiers.alt,
                                        shift: modifiers.shift,
                                        logo: modifiers.logo,
                                        level3: modifiers.iso_level3_shift,
                                        level5: modifiers.iso_level5_shift,
                                    },
                                )
                            })
                            .cloned();
                        if let Some(action) = action {
                            state.suppressed_keys.insert(code.raw());
                            FilterResult::Intercept(Some(action))
                        } else {
                            FilterResult::Forward
                        }
                    },
                )
                .flatten();
            if let Some(action) = action
                && let Err(error) = self.apply_action(action)
            {
                tracing::warn!(%error, "shortcut rejected");
            }
        }
        InputEvent::PointerMotion { event, .. } => {

        socket_name,

        compositor_state,
        xdg_shell_state,
        shm_state,
        _output_manager_state: output_manager_state,
        seat_state,
        data_device_state,
        popups,
        seat,
    };
    let keyboard = state.seat.get_keyboard().expect("keyboard added above");
    let defaults = crate::input::development_bindings();
    state.bindings = keyboard.with_xkb_state(&mut state, |context| {
        let xkb = context.xkb().lock().unwrap();
        // SAFETY: compile only borrows the keymap while this Xkb guard is
        // held. It retains pure Rust tables, no native object or refcount.
        flux_input::BindingSet::compile(
            &defaults,
            unsafe { xkb.keymap() },
            flux_input::UnmappedPolicy::RetainInactive,
        )
    })?;
    if !state.bindings.inactive_indices().is_empty() {
        tracing::info!(
            inactive = state.bindings.inactive_indices().len(),
            "development bindings absent from selected keymap"
        );
    }
    Ok(state)
}

